import itertools
from pysat.solvers import Glucose3

n = 14
num_colors = 5
possible_edges = list(itertools.combinations(range(n), 2))
num_edges = len(possible_edges)
e_var = {edge: idx + 1 for idx, edge in enumerate(possible_edges)}
color_var = {}
for v in range(n):
    for c in range(num_colors):
        color_var[(v, c)] = num_edges + v * num_colors + c + 1
total_vars = num_edges + n * num_colors

cnf = []

# Fixed edges must be present
fixed = [(1,4), (1,2), (1,9), (0,3)]
for a, b in fixed:
    edge = tuple(sorted((a, b)))
    cnf.append([e_var[edge]])

# No K5: for every set of 5 vertices, at least one edge missing
for five in itertools.combinations(range(n), 5):
    five_edges = [e_var[p] for p in itertools.combinations(five, 2)]
    cnf.append([-e for e in five_edges])

# Minimum degree at least 1
for v in range(n):
    incident = []
    for u in range(v):
        incident.append(e_var[(u, v)])
    for u in range(v+1, n):
        incident.append(e_var[(v, u)])
    cnf.append(incident)

# Each vertex gets exactly one color
for v in range(n):
    cnf.append([color_var[(v, c)] for c in range(num_colors)])
for v in range(n):
    for c1, c2 in itertools.combinations(range(num_colors), 2):
        cnf.append([-color_var[(v, c1)], -color_var[(v, c2)]])

# If edge present, different colors
for (u, v), evar in e_var.items():
    for c in range(num_colors):
        cnf.append([-evar, -color_var[(u, c)], -color_var[(v, c)]])

# Solve
solver = Glucose3(bootstrap_with=cnf)
satisfiable = solver.solve()
print("Satisfiable:", satisfiable)
if satisfiable:
    model = solver.get_model()
    sol = {abs(x): x > 0 for x in model}
    present_edges = []
    for edge, var in e_var.items():
        if sol.get(var, False):
            present_edges.append(edge)
    present_edges.sort()
    print("Number of edges:", len(present_edges))
    print("First 10 edges:", present_edges[:10])
    # flatten
    flat = [x for pair in present_edges for x in pair]
    print("Flat:", flat[:20], "...")

